package top.pxczxn.community.web.rss;
import jakarta.servlet.http.HttpServletRequest; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import top.pxczxn.community.rss.application.PublicRssService;
@RestController @RequiredArgsConstructor @RequestMapping("/api/v1/public/rss") public class PublicRssController { private final PublicRssService service; @GetMapping(value="/articles.xml",produces="application/rss+xml;charset=UTF-8") public ResponseEntity<String> site(HttpServletRequest r,@RequestHeader(value="If-None-Match",required=false)String tag){return response(service.site(origin(r)),tag);} @GetMapping(value="/blogs/{slug}.xml",produces="application/rss+xml;charset=UTF-8") public ResponseEntity<String> blog(@PathVariable String slug,HttpServletRequest r,@RequestHeader(value="If-None-Match",required=false)String tag){return response(service.blog(origin(r),slug),tag);} @GetMapping(value="/series/{id}.xml",produces="application/rss+xml;charset=UTF-8") public ResponseEntity<String> series(@PathVariable Long id,HttpServletRequest r,@RequestHeader(value="If-None-Match",required=false)String tag){return response(service.series(origin(r),id),tag);} @GetMapping(value="/tags/{slug}.xml",produces="application/rss+xml;charset=UTF-8") public ResponseEntity<String> tag(@PathVariable String slug,HttpServletRequest r,@RequestHeader(value="If-None-Match",required=false)String etag){return response(service.tag(origin(r),slug),etag);} private static ResponseEntity<String> response(PublicRssService.RssDocument d,String incoming){HttpHeaders h=new HttpHeaders();h.setContentType(MediaType.parseMediaType("application/rss+xml;charset=UTF-8"));h.setCacheControl(CacheControl.maxAge(java.time.Duration.ofMinutes(5)).cachePublic().mustRevalidate());h.setETag(d.etag());if(d.lastModified()!=null)h.setLastModified(d.lastModified().atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli());return d.etag().equals(incoming)?new ResponseEntity<>(null,h,HttpStatus.NOT_MODIFIED):new ResponseEntity<>(d.xml(),h,HttpStatus.OK);}private static String origin(HttpServletRequest r){return r.getScheme()+"://"+r.getServerName()+((r.getServerPort()==80||r.getServerPort()==443)?"":":"+r.getServerPort());}}
